-- Meraki App: textos de los pasos en palabras sencillas (sin tecnicismos),
-- cada paso se entiende solo y dice dónde poner la mano o la pelota.
-- No cambia la técnica ni los tiempos, solo título y detalle.

update public.pasos_zona
set detalle = 'Con la palma o las yemas de los dedos, desliza suave sobre toda la zona, con movimientos largos y livianos, sin presionar fuerte todavía. Así el músculo se calienta y la técnica siguiente duele menos y funciona mejor.'
where orden = 1 and detalle like 'Con la palma o las yemas de los dedos, desliza suavemente sobre toda la zona%';

update public.pasos_zona p set titulo = v.t, detalle = v.d
from (values
-- TRAPECIO (1-5)
(1,2,'Encuentra el punto','Siéntate con los brazos sueltos. Pon las yemas de los dedos en la parte de arriba del hombro, a medio camino entre el cuello y la punta del hombro. Ahí suele haber un punto duro y sensible. Puede que sientas la molestia subir hacia la sien o detrás del ojo.'),
(1,3,'Presiona en círculos','Con las yemas de los dedos, presiona firme (sin que duela fuerte) y haz círculos pequeños sobre el punto más duro. Respira lento.'),
(1,4,'Estiramiento final','Inclina la cabeza llevando la oreja hacia el hombro, sin subir el hombro. Quédate ahí, respirando.'),
(2,2,'Ponte en posición','Siéntate e inclina la cabeza un poco hacia el lado contrario al que vas a masajear. Así el músculo queda más fácil de alcanzar.'),
(2,3,'Presiona el borde del cuello','Con las yemas de los dedos, haz círculos pequeños en el borde del músculo, cerca del cuello (se siente como una cuerda gruesa entre el cuello y el hombro). Puede que sientas la molestia llegar hasta la mandíbula o la oreja.'),
(2,4,'Estiramiento final','Lleva la oreja hacia el hombro contrario y quédate ahí, respirando.'),
(3,2,'Ponte en posición','Sentada, cruza el brazo del lado que vas a trabajar sobre el pecho. Eso separa el omóplato (el hueso plano de la espalda) y deja libre el músculo de la mitad de la espalda.'),
(3,3,'Presiona la mitad de la espalda','Con los dedos de la otra mano, presiona el punto que queda entre el omóplato y la columna, en la parte alta de la espalda. Puede que sientas ardor en esa zona, es normal si es suave. Quédate ahí unos segundos.'),
(3,4,'Suelta despacio','Suelta la presión poco a poco y respira hondo dos veces.'),
(4,2,'Ponte en posición','Acuéstate boca abajo, o siéntate inclinada hacia adelante con el brazo colgando suelto. Así llegas a la parte más baja del músculo.'),
(4,3,'Presión más profunda','Nivel avanzado: busca el punto más bajo, pegado al borde del omóplato que da hacia la columna, y presiona más profundo y sostenido. Si duele demasiado, baja la fuerza enseguida.'),
(5,2,'Punto del hombro','Yemas de los dedos en la parte de arriba del hombro, entre el cuello y la punta; presiona en círculos.'),
(5,3,'Borde del cuello','Círculos en el borde del músculo, cerca del cuello.'),
(5,4,'Mitad de la espalda','Presión quieta en el punto entre el omóplato y la columna.'),
(5,5,'Punto bajo','Presión más profunda y quieta, pegada al borde del omóplato que da hacia la columna.'),
-- NUCA (6-10)
(6,2,'Encuentra el borde del cráneo','Pon las yemas de los dedos en la nuca y sube hasta sentir el hueso de la base de la cabeza, donde termina el cráneo y empieza el cuello. Busca a los lados de la columna, no sobre ella.'),
(6,3,'Presiona con los dedos','Presiona suave y sostenido en ese borde. Mueve la cabeza muy despacio, como diciendo sí y no, hasta encontrar el punto donde se siente más duro. Respira lento.'),
(6,4,'Cierra con las palmas','Con las palmas de ambas manos, abraza la base del cráneo y sostén una presión suave y constante, como un abrazo.'),
(7,2,'Encuentra el borde del cráneo','Vuelve al mismo borde donde termina el cráneo, a los lados de la columna.'),
(7,3,'Círculos pequeños','En vez de quedarte quieta, haz círculos pequeños con las yemas de los dedos sobre ese borde. Este roce suave suelta primero la tensión de arriba, antes de ir más profundo en el siguiente nivel.'),
(7,4,'Cierra con las palmas','Abraza la base del cráneo con las palmas y quédate unos segundos.'),
(8,2,'Encuentra el punto del lado','Muévete un poco hacia un lado, cerca de la base del cráneo, detrás de la oreja. Puede que sientas la molestia subir hacia la sien del mismo lado.'),
(8,3,'Presiona y respira','Sostén la presión con las yemas de los dedos, respirando lento.'),
(8,4,'Cierre','Abraza la base del cráneo con las palmas y suelta despacio.'),
(9,2,'Encuentra el punto del lado','Vuelve al punto de al lado, cerca de la base del cráneo, detrás de la oreja.'),
(9,3,'Presión con movimiento','Nivel avanzado: sostén la presión en ese punto y, al mismo tiempo, gira la cabeza muy despacio, como diciendo sí y no. El movimiento ayuda a soltar más que la presión quieta. Si sientes mareo o un dolor fuerte, baja la presión.'),
(9,4,'Cierra con las palmas','Abraza la base del cráneo y quédate quieta, respirando hondo.'),
(10,2,'Primer lado','Presión quieta en el borde del cráneo y en el punto de al lado, del primer lado.'),
(10,3,'Segundo lado','Repite lo mismo del otro lado.'),
(10,4,'Estiramiento final','Abraza la base del cráneo con ambas palmas y respira lento.'),
-- SIEN (11-15)
(11,2,'Encuentra la sien','Pon las yemas de los dedos en el costado de la cabeza, justo encima de la oreja. Ese es el músculo que usas para masticar.'),
(11,3,'Círculos lentos','Haz círculos lentos con las yemas de los dedos, desde la línea del cabello hacia adelante, hasta la esquina del ojo.'),
(11,4,'Combínalo con la mandíbula','Funciona mejor si después trabajas la zona de la mandíbula, que es otra zona de esta app.'),
(12,2,'Encuentra la sien','Pon las yemas de los dedos en el costado de la cabeza, por encima de la oreja.'),
(12,3,'Presión punto por punto','En vez de círculos, ve avanzando de a poquito: cada 2 o 3 centímetros detente y sostén una presión firme unos segundos antes de seguir. Llega más profundo que el círculo.'),
(12,4,'Cierre','Presión suave y quieta en el punto más duro.'),
(13,2,'Encuentra el punto de atrás','Busca la parte de atrás del mismo músculo, cerca de la línea del cabello, por encima y detrás de la oreja.'),
(13,3,'Círculos suaves','Haz círculos suaves y controlados en ese punto.'),
(14,2,'Sien','Círculos suaves en el punto de atrás de la sien.'),
(14,3,'Mejilla (mandíbula)','Nivel avanzado: pasa a presionar la mejilla, delante de la oreja, en el músculo con el que aprietas los dientes. Estos dos músculos suelen trabajar juntos cuando se aprietan los dientes.'),
(14,4,'Cierre','Presión suave final en los dos puntos.'),
(15,2,'Sien completa','Círculos desde la línea del cabello hasta el ojo, y luego en el punto de atrás.'),
(15,3,'Mandíbula','Círculos en el músculo de la mejilla, delante de la oreja.'),
(15,4,'Cierre','Presión suave y quieta en los dos puntos, respirando lento.'),
-- MANDIBULA (16-20)
(16,2,'Encuentra el músculo','Pon los dedos delante de las orejas y aprieta los dientes: sentirás que se abulta un músculo. Ese es el que vas a masajear. Después relaja la mandíbula.'),
(16,3,'Círculos suaves','Con las yemas de los dedos, haz círculos suaves y controlados sobre ese músculo.'),
(16,4,'Debajo del hueso de la mandíbula','Con la boca relajada, presiona suavemente con el pulgar justo debajo del hueso de la mandíbula.'),
(17,2,'Encuentra el músculo','Pon los dedos delante de las orejas, donde sentiste el músculo al apretar los dientes.'),
(17,3,'Presión con pulsos','En el mismo punto, presiona con el dedo contando 3 segundos, suelta 1 y repite. Ese ritmo afloja el músculo de otra forma que la presión quieta.'),
(17,4,'Cierre','Presión suave debajo del hueso de la mandíbula.'),
(18,2,'Encuentra el punto más profundo','Busca un poco más adentro y abajo, en la esquina de la mandíbula, donde el hueso hace como una L. Puede que sientas la molestia hacia el oído o los dientes.'),
(18,3,'Presión sostenida','Presiona con el pulgar o las yemas de los dedos, con calma, y respira lento.'),
(18,4,'Cierre','Suelta despacio.'),
(19,2,'Encuentra el punto más profundo','Vuelve a la esquina de la mandíbula, un poco más adentro y abajo.'),
(19,3,'Presión y movimiento suave','Nivel avanzado: sostén la presión mientras abres y cierras la boca muy despacio, unas cuantas veces.'),
(20,2,'Mejilla','Círculos suaves delante de la oreja, en el músculo de la mejilla.'),
(20,3,'Esquina de la mandíbula','Presión quieta, más adentro y abajo, en la esquina de la mandíbula.'),
-- HOMBRO (21-25)
(21,2,'Encuentra el músculo','Con la mano contraria, toca la parte de afuera del hombro, la zona redonda que se mueve cuando levantas el brazo.'),
(21,3,'Presión lenta','Desliza la mano despacio y con presión media, de arriba hacia abajo, siguiendo la línea del músculo.'),
(21,4,'Estiramiento final','Lleva el brazo cruzado hacia el pecho, suave, y sostén.'),
(22,2,'Encuentra el músculo','Con la mano contraria, toca la parte de afuera y del medio del hombro.'),
(22,3,'Amasa el músculo','En vez de deslizar, toma el músculo entre los dedos y el pulgar y amásalo suave, como si amasaras masa. Así llegas a partes que un solo deslizamiento no alcanza.'),
(22,4,'Estiramiento final','Lleva el brazo cruzado hacia el pecho y sostén.'),
(23,2,'Encuentra la parte de adelante','Con la mano contraria, toca la parte de adelante del hombro. Suele doler cuando levantas el brazo hacia adelante.'),
(23,3,'Presión lenta','Desliza despacio sobre esa parte, con presión media.'),
(23,4,'Cierre','Lleva el brazo cruzado hacia el pecho y sostén.'),
(24,2,'Ponte en posición','Lleva el brazo cruzado sobre el pecho y trabaja la parte de atrás del hombro con la mano contraria.'),
(24,3,'Presión más profunda','Nivel avanzado: presión más sostenida en la parte de atrás del hombro, que es más difícil de alcanzar.'),
(25,2,'Parte de afuera','Presión lenta de arriba hacia abajo en la parte de afuera del hombro.'),
(25,3,'Parte de adelante','Presión lenta en la parte de adelante del hombro.'),
(25,4,'Parte de atrás','Presión en la parte de atrás del hombro.'),
(25,5,'Estiramiento final','Brazo cruzado hacia el pecho, sostén respirando lento.'),
-- ESPALDA ALTA, ENTRE LOS OMOPLATOS (26-30)
(26,2,'Encuentra el borde del omóplato','Lleva la mano contraria por encima del hombro, o por el costado, y busca con los dedos el borde del omóplato (el hueso plano de la espalda) que queda del lado de la columna.'),
(26,3,'Presiona con los dedos','Con las yemas de los dedos, haz círculos pequeños sobre el músculo que queda al lado de ese borde. No presiones directo sobre el hueso.'),
(26,4,'Estiramiento final','Lleva ese brazo cruzado sobre el pecho, sostenido con la otra mano, para estirar suave la zona.'),
(27,2,'Encuentra el borde del omóplato','Busca otra vez el borde del omóplato que queda del lado de la columna.'),
(27,3,'Vaivén cruzado','En vez de quedarte quieta, mueve los dedos de lado a lado en vaivenes pequeños, cruzando el músculo, a lo largo de ese borde. Este roce cruzado suelta zonas pegadas que la presión quieta no alcanza.'),
(27,4,'Cierre','Brazo cruzado sobre el pecho, sostén.'),
(28,2,'Encuentra el punto de arriba','Busca la parte de arriba del omóplato, cerca de la columna, a la altura de la base del cuello.'),
(28,3,'Presiona con los dedos','Haz círculos pequeños y sostenidos sobre ese punto.'),
(28,4,'Cierre','Brazo cruzado sobre el pecho.'),
(29,2,'Encuentra el músculo hacia el cuello','Busca justo encima del omóplato, hacia el cuello. Casi siempre se tensa junto con el borde del omóplato.'),
(29,3,'Presión más profunda','Nivel avanzado: presión sostenida y un poco más profunda en ese punto.'),
(29,4,'Estiramiento final','Lleva suavemente la oreja hacia el hombro contrario.'),
(30,2,'Borde y punto de arriba','Presión con los dedos en los dos puntos del omóplato: el borde y la parte de arriba.'),
(30,3,'Músculo hacia el cuello','Presión sostenida en el músculo que sube del omóplato hacia el cuello.'),
(30,4,'Estiramiento final','Brazo cruzado sobre el pecho y oreja hacia el hombro contrario.'),
-- ESPALDA ALTA Y COSTADOS (31-35)
(31,2,'Ponte en posición','Acostada boca arriba o sentada, lleva la mano por encima del hombro contrario, hacia la parte alta de la espalda.'),
(31,3,'Presión con los nudillos','Con los nudillos o las yemas de los dedos, haz círculos pequeños buscando el punto más duro.'),
(31,4,'Sostén','Mantén la presión con los dedos, respirando lento.'),
(32,2,'Ponte en posición','Lleva la mano hacia la parte alta de la espalda.'),
(32,3,'Amasa con el puño','En vez de círculos, cierra la mano en puño y amasa la zona con un movimiento de vaivén, como si trabajaras masa.'),
(32,4,'Sostén','Respira lento manteniendo la presión.'),
(33,2,'Encuentra el borde de afuera','Busca el borde de afuera de la espalda, cerca de la axila. Puede que sientas la molestia hacia la parte de adentro del brazo.'),
(33,3,'Presión con los dedos','Círculos suaves y sostenidos sobre ese punto.'),
(34,2,'Encuentra el punto','Busca la punta de abajo del omóplato, el hueso plano de la espalda.'),
(34,3,'Presión más profunda','Nivel avanzado: con los nudillos, presión más profunda y sostenida en ese punto.'),
(35,2,'Punto del medio','Presión con los nudillos en la parte alta de la espalda.'),
(35,3,'Borde de afuera','Presión con los dedos cerca de la axila.'),
(35,4,'Punta del omóplato','Presión con los nudillos en la punta de abajo del omóplato.'),
-- ESPALDA BAJA (36-40)
(38,2,'Encuentra el punto del lado','Muévete un poco hacia el lado, cerca del hueso que sobresale en la cintura, arriba de la cadera. Puede que sientas la molestia hacia el glúteo.'),
(38,3,'Presión con el puño','Pon el puño en ese punto y deja caer el peso del cuerpo con calma.'),
(39,2,'Encuentra el punto del lado','Vuelve al punto del lado, cerca del hueso de la cintura, arriba de la cadera.'),
(39,3,'Presión con movimiento','Nivel avanzado: sostén el puño en ese punto mientras mueves las dos rodillas muy despacio de lado a lado. Ese movimiento ayuda a soltar más que la presión quieta. Baja la presión si el dolor se dispara hacia la pierna.'),
(40,2,'Primer lado','Puños a los lados de la columna y luego en el punto cerca del hueso de la cintura, del primer lado.'),
(40,3,'Segundo lado','Repite lo mismo del otro lado.'),
-- PIRIFORME (41-45)
(41,2,'Ponte en posición (con pelota o con la mano)','Lo más fácil es con una pelota de tenis. De pie, pon la pelota entre la pared y tu glúteo, del lado que quieres trabajar, y apóyate un poco contra la pared. Si no tienes pelota, siéntate o acuéstate de lado y cruza el tobillo de esa pierna sobre la rodilla contraria, para tener el glúteo a la mano.'),
(41,3,'Dónde poner la pelota','Busca la parte de arriba del glúteo, más o menos a medio camino entre el hueso plano que sientes al final de la espalda y el hueso que sobresale en el costado de la cadera. Pon ahí la pelota (o tus nudillos). Evita el centro exacto del glúteo, porque ahí pasa un nervio que no conviene presionar.'),
(41,4,'Presiona y respira','Deja caer el peso de tu cuerpo sobre la pelota (o presiona con el puño o los nudillos), firme pero sin que duela fuerte. Quédate quieta y respira lento hasta que termine el cronómetro. Es normal sentir que el músculo se va soltando hacia el final.'),
(42,2,'Ponte en posición','Igual que en el nivel anterior: la pelota entre la pared y tu glúteo, o el tobillo cruzado sobre la rodilla contraria si lo haces con la mano.'),
(42,3,'Presiona con pulsos','Vuelve al mismo punto de la pelota, pero ahora, en vez de quedarte quieta, presiona y suelta, presiona y suelta, contando 3 o 4 segundos cada vez. Repítelo varias veces seguidas. Ese ritmo suelta el músculo de otra forma que la presión quieta.'),
(43,2,'Sube un poquito la pelota','Desde el punto anterior, sube la pelota (o tus dedos) un poco hacia la espalda baja, hacia el hueso plano que sientes al final de la columna. Si sientes que la molestia baja hacia la pierna, baja la presión.'),
(43,3,'Presiona con calma','Presiona firme y con calma en ese punto con la pelota o los nudillos, y quédate quieta. Respira lento.'),
(44,2,'Baja un poquito la pelota','Ahora mueve la pelota (o tus dedos) hacia el costado, un poco más abajo del punto del centro, hacia el hueso que sobresale en el costado de la cadera. Quédate un poco antes de llegar al hueso, sobre el músculo.'),
(44,3,'Presión más profunda','Este nivel es avanzado: apoya más peso sobre la pelota, o presiona más profundo con el puño, sin moverte. Si el dolor se dispara hacia la pierna en vez de aliviarse, baja la presión de inmediato.'),
(45,2,'Punto del centro','Presión quieta con el puño o la pelota en el punto del centro, el mismo de los niveles anteriores.'),
(45,3,'Punto de arriba','Sube la pelota un poco hacia la espalda baja y presiona ahí, sin moverte.'),
(45,4,'Punto de abajo','Mueve la pelota hacia el costado de la cadera y presiona ahí, sin moverte.'),
-- PANTORRILLAS (46-50)
(46,2,'Posición','Siéntate con la pierna estirada.'),
(46,3,'Desliza hacia arriba','Con las dos manos rodeando la pantorrilla, desliza desde el tobillo hacia la rodilla, siempre hacia arriba, con presión media.'),
(46,4,'Piernas en la pared','Acuéstate y apoya las piernas elevadas contra la pared, moviendo los pies suavemente.'),
(47,2,'Posición','Siéntate con la pierna estirada.'),
(47,3,'Amasa la pantorrilla','En vez de deslizar en línea recta, toma el músculo entre los dedos y el pulgar y amásalo de lado a lado, como si amasaras masa.'),
(47,4,'Piernas en la pared','Acuéstate y apoya las piernas elevadas contra la pared.'),
(48,2,'Encuentra el lado de adentro','Busca el lado de adentro de la pantorrilla, el que queda hacia la otra pierna. Puede que sientas la molestia hacia el arco del pie.'),
(48,3,'Presión con los dedos','Presiona en círculos pequeños a lo largo del lado de adentro.'),
(48,4,'Cierre','Desliza suave hacia arriba para cerrar.'),
(49,2,'Encuentra la parte de abajo','Busca más abajo y más profundo, cerca del tendón grueso que está encima del talón. Puede que sientas la molestia hacia el talón.'),
(49,3,'Presión más profunda','Nivel avanzado: presión sostenida y más profunda en ese punto.'),
(49,4,'Cierre','Desliza suave hacia arriba.'),
(50,2,'Desliza hacia arriba','Desde el tobillo hacia la rodilla, con presión media.'),
(50,3,'Lado de adentro','Presión en el lado de adentro de la pantorrilla.'),
(50,4,'Parte de abajo','Presión profunda cerca del tendón que está encima del talón.'),
(50,5,'Piernas en la pared','Acuéstate y apoya las piernas elevadas contra la pared.'),
-- PLANTA DEL PIE (51-55)
(51,2,'Posición','Sentada, cruza el pie que vas a trabajar sobre la rodilla contraria para tenerlo a la mano.'),
(51,3,'Presión con los pulgares','Con ambos pulgares, presiona en círculos pequeños desde el talón hacia los dedos.'),
(51,4,'Puntos sensibles','Detente 20 a 30 segundos en los puntos que sientas más sensibles.'),
(52,2,'Posición','Cruza el pie sobre la rodilla contraria.'),
(52,3,'Círculos con los pulgares','En vez de ir en línea del talón a los dedos, cubre toda la planta con círculos pequeños y firmes de los pulgares, de lado a lado. Llegas a zonas que el recorrido en línea no cubre.'),
(52,4,'Puntos sensibles','Detente en los puntos más sensibles.'),
(53,2,'Encuentra el centro del arco','Con los pulgares, busca el punto del medio del arco, la parte curva de abajo del pie.'),
(53,3,'Presión sostenida','Presiona con calma en ese punto.'),
(54,2,'Planta','Presión quieta en el centro del arco del pie.'),
(54,3,'Pantorrilla','Nivel avanzado: suma presión profunda en la parte de abajo de la pantorrilla, cerca del talón. Muchas veces el dolor de la planta viene de ahí.'),
(54,4,'Cierre','Desliza suave hacia arriba.'),
(55,2,'Del talón a los dedos','Presión con los pulgares desde el talón hacia los dedos.'),
(55,3,'Centro del arco','Presión quieta en el centro del arco.'),
(55,4,'Pantorrilla','Presión profunda en la pantorrilla, cerca del tendón que está encima del talón.'),
(55,5,'Cierre','Desliza suave hacia arriba para terminar.'),
-- ANTEBRAZO (56-60)
(56,2,'Parte de arriba del antebrazo','Apoya el antebrazo en una mesa, con la palma hacia abajo. Haz círculos suaves, con presión media, desde la muñeca hasta el codo.'),
(56,3,'Parte de abajo del antebrazo','Ahora con la palma hacia arriba, haz los mismos círculos desde la muñeca hasta el codo.'),
(56,4,'Estiramiento','Con el brazo estirado, dobla la muñeca hacia abajo y luego hacia arriba.'),
(57,2,'Parte de arriba, con vaivén','En vez de círculos, mueve los dedos de lado a lado en vaivenes pequeños, cruzando el músculo, desde la muñeca hasta el codo.'),
(57,3,'Parte de abajo, con vaivén','El mismo vaivén cruzado, ahora del lado de la palma.'),
(57,4,'Estiramiento','Dobla la muñeca hacia abajo y luego hacia arriba.'),
(58,2,'Encuentra el punto','Busca cerca del codo, en el lado de afuera del antebrazo (el lado del pulgar cuando tienes la palma hacia arriba).'),
(58,3,'Presión con los dedos','Haz círculos suaves y sostenidos en ese punto.'),
(58,4,'Cierre','Estira suave la muñeca hacia abajo.'),
(59,2,'Encuentra el punto','Busca cerca del codo, en el lado de adentro del antebrazo (el lado del meñique cuando tienes la palma hacia arriba).'),
(59,3,'Presión más profunda','Nivel avanzado: presión más profunda y sostenida en ese punto.'),
(59,4,'Cierre','Estira suave la muñeca hacia arriba.'),
(60,2,'Parte de arriba del antebrazo','Círculos desde la muñeca hasta el codo.'),
(60,3,'Parte de abajo del antebrazo','El mismo recorrido del lado de la palma.'),
(60,4,'Lado de afuera del codo','Presión sostenida cerca del codo, en el lado de afuera.'),
(60,5,'Lado de adentro del codo','Presión sostenida cerca del codo, en el lado de adentro.'),
(60,6,'Estiramiento final','Dobla la muñeca hacia abajo y hacia arriba.'),
-- MANO Y MUÑECA (61-65)
(61,2,'Palma','Con el pulgar de la otra mano, haz círculos desde el centro de la palma hacia los dedos.'),
(61,3,'Entre los dedos','Presión suave en la base de cada dedo.'),
(61,4,'Muñeca','Círculos suaves alrededor de la muñeca.'),
(62,2,'Palma, con pulsos','En vez de círculos, presiona con el pulgar puntos distintos de la palma, contando 2 o 3 segundos y soltando, y avanza hacia los dedos.'),
(63,2,'Encuentra la base del pulgar','Con el pulgar de la otra mano, busca la base de tu propio pulgar, la parte carnosa de la palma.'),
(63,3,'Presión sostenida','Haz círculos suaves y sostenidos en ese punto.'),
(63,4,'Cierre','Círculos suaves alrededor de la muñeca.'),
(64,2,'Encuentra los espacios','Busca los espacios entre los huesos de los dedos, en la parte de atrás de la mano.'),
(64,3,'Presión suave','Nivel avanzado: presión fina y controlada en cada espacio, con el pulgar o con un dedo.'),
(64,4,'Cierre','Círculos suaves en la muñeca.'),
(65,2,'Palma','Círculos desde el centro hacia los dedos.'),
(65,3,'Base del pulgar','Presión sostenida en la base del pulgar.'),
(65,4,'Espacios entre los dedos','Presión suave en cada espacio entre los huesos de los dedos.'),
(65,5,'Muñeca','Círculos suaves para cerrar.'),
-- PECHO (66-70)
(66,2,'Ponte en posición','Sentada o de pie. Usa la mano contraria al lado que vas a masajear.'),
(66,3,'Amasa el pecho','Desde el hueso del centro del pecho hacia el costado, amasa suave con los dedos.'),
(66,4,'Estiramiento','Apoya el antebrazo en una esquina o en el marco de una puerta y gira el cuerpo hacia el lado contrario.'),
(67,2,'Ponte en posición','Usa la mano contraria al lado que vas a masajear.'),
(67,3,'Puntos concretos','En vez de amasar todo el recorrido, detente en 3 o 4 puntos entre el centro del pecho y el costado y sostén presión firme unos segundos en cada uno.'),
(67,4,'Estiramiento','Apoya el antebrazo en el marco de una puerta y gira el cuerpo.'),
(68,2,'Encuentra el punto','Busca la parte alta del pecho, cerca del hueso que queda debajo del cuello. Puede que sientas la molestia hacia el hombro.'),
(68,3,'Presión suave','Haz círculos suaves y sostenidos en ese punto.'),
(68,4,'Cierre','Estiramiento en el marco de una puerta.'),
(69,2,'Encuentra el punto','Busca debajo del músculo grande del pecho, cerca de la axila. Es una zona sensible.'),
(69,3,'Presión suave y gradual','Nivel avanzado: presiona suave y poco a poco, nunca brusco, en ese punto.'),
(69,4,'Cierre','Estiramiento suave en el marco de una puerta.'),
(70,2,'Amasa en general','Desde el centro del pecho hacia el costado.'),
(70,3,'Parte alta','Presión suave cerca del hueso que queda debajo del cuello.'),
(70,4,'Cerca de la axila','Presión suave y gradual cerca de la axila.'),
(70,5,'Estiramiento final','Antebrazo en el marco de una puerta y giro del cuerpo.'),
-- ABDOMEN (71-75)
(71,2,'Posición','Acostada boca arriba, con las rodillas dobladas y las manos relajadas sobre el abdomen.'),
(71,3,'Círculos suaves','Con las yemas de los dedos, haz círculos suaves sobre el abdomen, en el sentido de las agujas del reloj.'),
(72,3,'Cuatro puntos alrededor del ombligo','En vez de un círculo continuo, presiona con suavidad en 4 puntos alrededor del ombligo (arriba, a un lado, abajo y al otro lado, en el sentido de las agujas del reloj), sosteniendo unos segundos en cada uno.'),
(73,2,'Encuentra el punto','Busca justo debajo del hueso del centro del pecho, donde terminan las costillas. Puede que sientas una pesadez parecida a la de la digestión.'),
(73,3,'Presión suave','Haz círculos muy suaves en ese punto, nunca profundos.'),
(74,2,'Encuentra el punto','Busca un poco debajo del ombligo.'),
(74,3,'Presión suave y controlada','Es un nivel avanzado en tiempo, pero la presión sigue siendo suave y controlada, nunca profunda ni brusca en esta zona.'),
(75,2,'Círculos generales','Círculos suaves en el sentido de las agujas del reloj.'),
(75,3,'Debajo del pecho','Círculos muy suaves justo debajo del hueso del centro del pecho.'),
(75,4,'Debajo del ombligo','Presión suave y controlada.')
) as v(n, o, t, d)
where p.nivel_id = v.n and p.orden = v.o;
